  const s3 = new S3Client({
    endpoint: ENDPOINT,
    region: REGION,
    credentials: { accessKeyId, secretAccessKey },
    forcePathStyle: true,
  });

  const config = {
    endpoint: ENDPOINT,
    accessKeyId,
    secretAccessKey,
  };

  // Step 2: Upload v1.txt with body `version=1`.
  {
